<?php require_once __DIR__.'/../core.php'; require_once __DIR__.'/auth.php'; $items=data_list('hotels'); if($_SERVER['REQUEST_METHOD']==='POST'){if(geah_media_post($items,'hotels')){data_save('hotels',$items);header('Location:/admin/hotels.php');exit;} if(isset($_POST['delete'])){$id=(int)$_POST['delete'];$items=array_values(array_filter($items,fn($x)=>($x['id']??0)!=$id));}else{$new=['id'=>time(),'date'=>now()];$new['title']=$_POST['title']??'';$new['city']=$_POST['city']??'';$new['stars']=$_POST['stars']??'';$new['price']=$_POST['price']??'';$new['price_fcfa']=(int)($_POST['price_fcfa']??0);$new['status']=$_POST['status']??'';$new['latitude']=$_POST['latitude']??'';$new['longitude']=$_POST['longitude']??'';$new['description']=$_POST['description']??'';$new['images']=geah_upload_files('photos','hotels',['jpg','jpeg','png','webp','gif']);$gv=geah_upload_files('video_file','hotels',['mp4','webm','mov','ogg']);$new['video_url']=$gv[0]??trim($_POST['video_url']??'');$items[]=$new;} data_save('hotels',$items); header('Location:/admin/hotels.php'); exit;} ?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/style.css?v=110"></head><body><div class="admin-layout"><?php include __DIR__.'/sidebar.php'; ?><main class="admin-main"><h1>Hôtels</h1><p style="color:#6b7280;font-size:13px">📌 Ajoute les photos directement sur chaque élément, dans la section « Photos & vidéos » plus bas. 👇</p><form class="card" method="post" enctype="multipart/form-data"><div class="form-grid"><label>Nom hôtel<input type="text" name="title"></label><label>Ville<input type="text" name="city"></label><label>Étoiles<input type="text" name="stars"></label><label>Prix à partir de<input type="text" name="price"></label><label>💳 Prix à payer en ligne (FCFA)<input type="number" name="price_fcfa" min="0" placeholder="Ex: 25000"></label><label>Statut<select name="status"><option>Disponible</option><option>Complet</option><option>Partenaire</option><option>Maintenance</option></select></label><label>Latitude<input type="text" name="latitude"></label><label>Longitude<input type="text" name="longitude"></label><label class="full">Description<textarea name="description" rows="4"></textarea></label><label>📷 Photos (plusieurs)<input type="file" name="photos[]" accept="image/*" multiple></label><label>🎬 Vidéo<input type="file" name="video_file" accept="video/*"></label><label>… ou lien vidéo<input type="text" name="video_url" placeholder="YouTube..."></label></div><button class="btn btn-primary">Ajouter</button></form><table class="table"><tr><th>ID</th><th>Nom hôtel</th><th>Ville</th><th>Étoiles</th><th>Prix à partir de</th><th>Statut</th><th>Latitude</th><th>Longitude</th><th>Description</th><th></th></tr><?php foreach(array_reverse($items) as $item): ?><tr><td><?=e($item['id']??'')?></td><td><?=e($item['title']??'')?></td><td><?=e($item['city']??'')?></td><td><?=e($item['stars']??'')?></td><td><?=e($item['price']??'')?></td><td><?=e($item['status']??'')?></td><td><?=e($item['latitude']??'')?></td><td><?=e($item['longitude']??'')?></td><td><?=e($item['description']??'')?></td><td><form method="post"><button class="btn danger" name="delete" value="<?=e($item['id'])?>">Supprimer</button></form></td></tr><?php endforeach; ?></table><h2>📷 Photos & vidéos par élément</h2><?php foreach(array_reverse($items) as $item): ?><div class="card"><h3><?=e($item['title']??'')?></h3><?=geah_media_block($item)?></div><?php endforeach; ?></main></div><script>
(function(){const saved=localStorage.getItem('geah_theme')||'dark';if(saved==='light')document.body.classList.add('light-mode');function ready(){const btn=document.createElement('button');btn.className='theme-toggle';function label(){btn.textContent=document.body.classList.contains('light-mode')?'🌙 Mode sombre':'☀️ Mode clair'}btn.onclick=function(){document.body.classList.toggle('light-mode');localStorage.setItem('geah_theme',document.body.classList.contains('light-mode')?'light':'dark');label()};label();document.body.appendChild(btn)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready);else ready();})();
</script></body></html>